    """Claude Code's PreToolUse matcher rule: empty, missing or ``*``
    matches every tool; otherwise the pattern is a regular expression the
    whole tool name must match (so a plain name matches exactly and
    ``Edit|Write`` matches either)."""
    if pattern in (None, "", "*"):
