class TestCallerHookDenialLeavesNoReservation:
    """A call another PreToolUse hook denies never runs, so no PostToolUse
    or PostToolUseFailure ends a reservation taken for it. The adapter
    runs the caller's hooks first and reserves only if none denied."""

    WRITE = {"tool_name": "Write", "tool_input": {"file_path": "a.txt"}}

    @pytest.mark.asyncio
    async def test_caller_denial_reserves_nothing_and_charges_nothing(
        self, strict_adapter: GroundedAgentAdapter
    ):
        strict_adapter.create_checkpoint(["*"], "Test")
        charged: list[str] = []
        allow = strict_adapter.rate_limiter.allow

        def counting_allow(risk: str) -> bool:
            charged.append(risk)
            return allow(risk)

        strict_adapter.rate_limiter.allow = counting_allow  # type: ignore[method-assign]

        async def deny_writes(input_data, tool_use_id, context):
            return _deny("caller policy")

        hook = _pre_hook(
            strict_adapter,
            ClaudeAgentOptions(
                hooks={"PreToolUse": [{"matcher": "Write", "hooks": [deny_writes]}]}
            ),
        )
        result = await hook(self.WRITE, "w1", None)

        assert _reason(result) == "caller policy"
        assert charged == []
        assert strict_adapter.checkpoint_tracker.validate_and_reserve("w2")[0]

    @pytest.mark.asyncio
    async def test_caller_hook_for_other_tools_is_skipped(
        self, strict_adapter: GroundedAgentAdapter
    ):
        strict_adapter.create_checkpoint(["*"], "Test")

        async def deny_bash(input_data, tool_use_id, context):
            return _deny("no bash")

        hook = _pre_hook(
            strict_adapter,
            ClaudeAgentOptions(
                hooks={"PreToolUse": [{"matcher": "Bash|Edit", "hooks": [deny_bash]}]}
            ),
        )

        assert await hook(self.WRITE, "w1", None) == {}
        # The Write went ahead and holds the checkpoint.
        assert not strict_adapter.checkpoint_tracker.validate_and_reserve("w2")[0]

    @pytest.mark.asyncio
    async def test_raising_caller_hook_is_no_decision_by_default(
        self, strict_adapter: GroundedAgentAdapter
    ):
        strict_adapter.create_checkpoint(["*"], "Test")

        async def broken(input_data, tool_use_id, context):
            raise RuntimeError("caller bug")

        hook = _pre_hook(
            strict_adapter,
            ClaudeAgentOptions(hooks={"PreToolUse": [{"hooks": [broken]}]}),
        )

        assert await hook(self.WRITE, "w1", None) == {}
        assert strict_adapter.checkpoint_tracker.validate_and_reserve("w1")[0]

    @pytest.mark.asyncio
    async def test_raising_caller_hook_blocks_when_matcher_says_so(
        self, strict_adapter: GroundedAgentAdapter
    ):
        from claude_agent_sdk import HookMatcher

        strict_adapter.create_checkpoint(["*"], "Test")

        async def broken(input_data, tool_use_id, context):
            raise RuntimeError("caller bug")

        hook = _pre_hook(
            strict_adapter,
            ClaudeAgentOptions(
                hooks={"PreToolUse": [HookMatcher(hooks=[broken], on_failure="block")]}
